            potluckItems.push(newItem);
        }

        saveAndRender();
        form.reset();
        document.getElementById('neighbor').focus();
    });

    function startEdit(id) {
        const itemToEdit = potluckItems.find(item => item.id === id);
        if (!itemToEdit) return;

        editTargetId = id;

        // Load target details directly back into form inputs
        document.getElementById('neighbor').value = itemToEdit.neighbor;
        document.getElementById('category').value = itemToEdit.category;
        document.getElementById('dish').value = itemToEdit.dish;

        // Alter form wrapper UI appearance contextually
        formCard.classList.add('editing');
        submitBtn.innerText = 'Update Entry';
        cancelBtn.style.display = 'inline-block';

        renderList();
        document.getElementById('neighbor').focus();
    }

    function resetFormState() {
        editTargetId = null;
        form.reset();
        formCard.classList.remove('editing');
        submitBtn.innerText = 'Add to List';
        cancelBtn.style.display = 'none';
        renderList();
    }

    function deleteItem(id) {
        if (editTargetId === id) {
            resetFormState();
        }
        potluckItems = potluckItems.filter(item => item.id !== id);
        saveAndRender();
    }

    function saveAndRender() {
        localStorage.setItem('potluckItems', JSON.stringify(potluckItems));
        renderList();
        updateDashboard();
    }

    function updateDashboard() {
        const counts = { main: 0, side: 0, dessert: 0, drink: 0 };

        potluckItems.forEach(item => {
            if (counts.hasOwnProperty(item.category)) {
                counts[item.category]++;
            }
        });

        // Update DOM display metrics
        for (const cat in counts) {
            document.getElementById(`count-${cat}`).innerText = counts[cat];
        }

        // Trigger Dessert Warning: logic handles scenarios where desserts strictly outnumber main dishes
        const dessertCard = document.getElementById('card-dessert');
        const dessertWarnText = document.getElementById('warn-dessert');

        if (counts.dessert > counts.main && counts.dessert > 0) {
            dessertCard.classList.add('warning');
            dessertWarnText.style.display = 'block';
        } else {
            dessertCard.classList.remove('warning');
            dessertWarnText.style.display = 'none';
        }
    }

    function renderList() {
        if (potluckItems.length === 0) {
            listContainer.innerHTML = '<div class="empty-state">No sign-ups yet. Add the first neighbor above!</div>';
            return;
        }

        // Sort order helper object
        const order = { main: 1, side: 2, dessert: 3, drink: 4 };
        const sortedItems = [...potluckItems].sort((a, b) => order[a.category] - order[b.category]);

        listContainer.innerHTML = sortedItems.map(item => {
            const isTarget = item.id === editTargetId;
            return `
                <div class="item-row ${isTarget ? 'is-editing' : ''}">
                    <div class="item-details">
                        <span class="badge badge-${item.category}">${item.category}</span>
                        <span class="neighbor-name">${escapeHTML(item.neighbor)}:</span>
                        <span class="dish-name">${escapeHTML(item.dish)}</span>
                    </div>
                    <div class="action-buttons">
                        <button type="button" class="btn-action btn-edit-item" onclick="startEdit(${item.id})">Edit</button>
                        <button type="button" class="btn-action btn-delete-item" onclick="deleteItem(${item.id})">Remove</button>
                    </div>
                </div>
            `;
        }).join('');
    }

    function copyCleanList() {
        if (potluckItems.length === 0) return;

        const order = { main: 'MAINS', side: 'SIDES', dessert: 'DESSERTS', drink: 'DRINKS' };
        let textOutput = "POTLUCK BRING-LIST\n==================\n";

        for (const [key, label] of Object.entries(order)) {
            const catItems = potluckItems.filter(item => item.category === key);
            if (catItems.length > 0) {
                textOutput += `\n${label}:\n`;
                catItems.forEach(item => {
                    textOutput += `- ${item.dish} (${item.neighbor})\n`;
                });
            }
        }

        navigator.clipboard.writeText(textOutput.trim()).then(() => {
            const feedback = document.getElementById('copyFeedback');
            feedback.style.opacity = '1';
            setTimeout(() => { feedback.style.opacity = '0'; }, 2000);
        });
    }

    function escapeHTML(str) {
        return str.replace(/[&<>'"]/g, 
            tag => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[tag] || tag)
        );
    }

    // App Initialization
    renderList();
    updateDashboard();
</script>

</body>
